+
+class ReachabilityTracker
+{
+public:
+    ReachabilityTracker()
+    {
+        const char* enforce{std::getenv("FUZZ_ENFORCE_REACHABILITY")};
+        if (!enforce || std::string_view{enforce} == "0") return;
+        if (std::string_view{enforce} == "1") {
+            m_enforce = true;
+            return;
+        }
+        std::fprintf(stderr, "FUZZ_ENFORCE_REACHABILITY must be 0 or 1.\n");
+        std::abort();
+    }
+
+    ~ReachabilityTracker()
+    {
+        std::lock_guard lock{m_mutex};
+        bool all_reached{true};
+        for (const auto& [id, reached] : m_goals) {
+            std::cerr << (reached ? "PASS" : "FAIL") << " reachability goal "
+                      << id.file_name << ':' << id.line << ':' << id.column << '\n';
+            all_reached &= reached;
+        }
+        if (m_enforce && !all_reached) {
+            std::cerr.flush();
+            std::_Exit(EXIT_FAILURE);
+        }
+    }
+
+    void Observe(bool reached, std::source_location location)
+    {
+        const GoalId id{
+            .file_name = location.file_name(),
+            .line = location.line(),
+            .column = location.column(),
+        };
+        std::lock_guard lock{m_mutex};
+        auto& goal{m_goals[id]};
+        goal |= reached;
+    }
+
+private:
+    std::map<GoalId, bool> m_goals;
+    std::mutex m_mutex;
